1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
RDMA/mlx4: Fix resource leak on error in mlx4_ib_create_srq()

Sashiko points out that mlx4_srq_alloc() was not undone during error
unwind, add the missing call to mlx4_srq_free().

Cc: stable@vger.kernel.org
Fixes: 225c7b1feef1 ("IB/mlx4: Add a driver Mellanox ConnectX InfiniBand adapters")
Link: https://sashiko.dev/#/patchset/0-v1-e911b76a94d1%2B65d95-rdma_udata_rep_jgg%40nvidia.com?part=8
Link: https://patch.msgid.link/r/11-v1-41f3135e5565+9d2-rdma_ai_fixes1_jgg@nvidia.com
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>

Here is the root cause:
In the function `mlx4_ib_create_srq()`, when the call to `ib_copy_to_udata()` fails, the error handling jumps to the `err_wrid` label which only unmaps the user database but does not free the SRQ structure that was previously allocated by `mlx4_srq_alloc()`. This missing `mlx4_srq_free()` call causes a resource leak whenever the copy to user space fails after a successful SRQ allocation.

Here is the patch:

 int mlx4_ib_create_srq(struct ib_srq *ib_srq,
 		       struct ib_srq_init_attr *init_attr,
 		       struct ib_udata *udata)
 {
 	struct mlx4_ib_dev *dev = to_mdev(ib_srq->device);
 	struct mlx4_ib_ucontext *ucontext = rdma_udata_to_drv_context(
 		udata, struct mlx4_ib_ucontext, ibucontext);
 	struct mlx4_ib_srq *srq = to_msrq(ib_srq);
 	struct mlx4_wqe_srq_next_seg *next;
 	struct mlx4_wqe_data_seg *scatter;
 	u32 cqn;
 	u16 xrcdn;
 	int desc_size;
 	int buf_size;
 	int err;
 	int i;

 	if (init_attr->srq_type != IB_SRQT_BASIC &&
 	    init_attr->srq_type != IB_SRQT_XRC)
 		return -EOPNOTSUPP;

 	/* Sanity check SRQ size before proceeding */
 	if (init_attr->attr.max_wr  >= dev->dev->caps.max_srq_wqes ||
 	    init_attr->attr.max_sge >  dev->dev->caps.max_srq_sge)
 		return -EINVAL;

 	mutex_init(&srq->mutex);
 	spin_lock_init(&srq->lock);
 	srq->msrq.max    = roundup_pow_of_two(init_attr->attr.max_wr + 1);
 	srq->msrq.max_gs = init_attr->attr.max_sge;

 	desc_size = max(32UL,
 			roundup_pow_of_two(sizeof (struct mlx4_wqe_srq_next_seg) +
 					   srq->msrq.max_gs *
 					   sizeof (struct mlx4_wqe_data_seg)));
 	srq->msrq.wqe_shift = ilog2(desc_size);

 	buf_size = srq->msrq.max * desc_size;

 	if (udata) {
 		struct mlx4_ib_create_srq ucmd;

 		err = ib_copy_validate_udata_in(udata, ucmd, db_addr);
 		if (err)
 			return err;

 		srq->umem =
 			ib_umem_get(ib_srq->device, ucmd.buf_addr, buf_size, 0);
 		if (IS_ERR(srq->umem))
 			return PTR_ERR(srq->umem);

 		err = mlx4_mtt_init(
 			dev->dev, ib_umem_num_dma_blocks(srq->umem, PAGE_SIZE),
 			PAGE_SHIFT, &srq->mtt);
 		if (err)
 			goto err_buf;

 		err = mlx4_ib_umem_write_mtt(dev, &srq->mtt, srq->umem);
 		if (err)
 			goto err_mtt;

 		err = mlx4_ib_db_map_user(udata, ucmd.db_addr, &srq->db);
 		if (err)
 			goto err_mtt;
 	} else {
 		err = mlx4_db_alloc(dev->dev, &srq->db, 0);
 		if (err)
 			return err;

 		*srq->db.db = 0;

 		if (mlx4_buf_alloc(dev->dev, buf_size, PAGE_SIZE * 2,
 				   &srq->buf)) {
 			err = -ENOMEM;
 			goto err_db;
 		}

 		srq->head    = 0;
 		srq->tail    = srq->msrq.max - 1;
 		srq->wqe_ctr = 0;

 		for (i = 0; i < srq->msrq.max; ++i) {
 			next = get_wqe(srq, i);
 			next->next_wqe_index =
 				cpu_to_be16((i + 1) & (srq->msrq.max - 1));

 			for (scatter = (void *) (next + 1);
 			     (void *) scatter < (void *) next + desc_size;
 			     ++scatter)
 				scatter->lkey = cpu_to_be32(MLX4_INVALID_LKEY);
 		}

 		err = mlx4_mtt_init(dev->dev, srq->buf.npages, srq->buf.page_shift,
 				    &srq->mtt);
 		if (err)
 			goto err_buf;

 		err = mlx4_buf_write_mtt(dev->dev, &srq->mtt, &srq->buf);
 		if (err)
 			goto err_mtt;

 		srq->wrid = kvmalloc_array(srq->msrq.max,
 					   sizeof(u64), GFP_KERNEL);
 		if (!srq->wrid) {
 			err = -ENOMEM;
 			goto err_mtt;
 		}
 	}

 	cqn = ib_srq_has_cq(init_attr->srq_type) ?
 		to_mcq(init_attr->ext.cq)->mcq.cqn : 0;
 	xrcdn = (init_attr->srq_type == IB_SRQT_XRC) ?
 		to_mxrcd(init_attr->ext.xrc.xrcd)->xrcdn :
 		(u16) dev->dev->caps.reserved_xrcds;
 	err = mlx4_srq_alloc(dev->dev, to_mpd(ib_srq->pd)->pdn, cqn, xrcdn,
 			     &srq->mtt, srq->db.dma, &srq->msrq);
 	if (err)
 		goto err_wrid;

 	srq->msrq.event = mlx4_ib_srq_event;
 	srq->ibsrq.ext.xrc.srq_num = srq->msrq.srqn;

 	if (udata)
 		if (ib_copy_to_udata(udata, &srq->msrq.srqn, sizeof (__u32))) {
 			err = -EFAULT;
-			goto err_wrid;
+			goto err_srq;
 		}

 	init_attr->attr.max_wr = srq->msrq.max - 1;

 	return 0;

+err_srq:
+	mlx4_srq_free(dev->dev, &srq->msrq);
 err_wrid:
 	if (udata)
 		mlx4_ib_db_unmap_user(ucontext, &srq->db);
 	else
 		kvfree(srq->wrid);

 err_mtt:
 	mlx4_mtt_cleanup(dev->dev, &srq->mtt);

 err_buf:
 	if (!srq->umem)
 		mlx4_buf_free(dev->dev, buf_size, &srq->buf);
 	ib_umem_release(srq->umem);

 err_db:
 	if (!udata)
 		mlx4_db_free(dev->dev, &srq->db);

 	return err;
 }



